local function decodeEmbeddedBase64(value)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local output = {}
    local buffer = 0
    local bits = 0
    for index = 1, #value do
        local character = value:sub(index, index)
        if character == "=" then
            break
        end
        local position = alphabet:find(character, 1, true)
        if position then
            buffer = buffer * 64 + position - 1
            bits += 6
            if bits >= 8 then
                bits -= 8
                output[#output + 1] = string.char(math.floor(buffer / 2 ^ bits) % 256)
                buffer %= 2 ^ bits
            end
        end
    end
    return table.concat(output)
end

local function resolveEmbeddedIcon(path, data, fallback)
    local cryptApi = rawget(Environment, "crypt") or rawget(_G, "crypt")
    local base64Api = type(cryptApi) == "table" and rawget(cryptApi, "base64") or nil
    local decoder = rawget(Environment, "base64_decode") or rawget(Environment, "base64decode")
        or (type(cryptApi) == "table" and (rawget(cryptApi, "base64decode") or rawget(cryptApi, "base64_decode")))
        or (type(base64Api) == "table" and (rawget(base64Api, "decode") or rawget(base64Api, "Decode")))
	local pngSignature = string.char(137, 80, 78, 71, 13, 10, 26, 10)
    local writer = rawget(Environment, "writefile")
    local customAsset = rawget(Environment, "getcustomasset") or rawget(Environment, "getsynasset")
    if type(customAsset) == "function" then
        local fileExists = rawget(Environment, "isfile")
        if type(fileExists) == "function" then
            local checked, exists = pcall(fileExists, path)
            if checked and exists then
                local loaded, asset = pcall(customAsset, path)
                if loaded and type(asset) == "string" and asset ~= "" then
                    return asset
                end
            end
        end
        if type(writer) == "function" then
            local makeFolder = rawget(Environment, "makefolder")
            local isFolder = rawget(Environment, "isfolder")
            if type(makeFolder) == "function" then
                pcall(function()
                    if type(isFolder) ~= "function" or not isFolder("Young0xHub") then
                        makeFolder("Young0xHub")
                    end
                end)
            end
            local decoded, bytes = pcall(type(decoder) == "function" and decoder or decodeEmbeddedBase64, data)
            if not decoded or type(bytes) ~= "string" or bytes:sub(1, 8) ~= pngSignature then
                bytes = decodeEmbeddedBase64(data)
            end
            if type(bytes) == "string" and bytes:sub(1, 8) == pngSignature then
                local written = pcall(writer, path, bytes)
                if written then
                    local loaded, asset = pcall(customAsset, path)
                    if loaded and type(asset) == "string" and asset ~= "" then
                        return asset
                    end
                end
            end
        end
    end
    return fallback
end

